    }

    #board {
      display: grid;
      grid-template-columns: repeat(4, 100px);
      grid-template-rows: repeat(4, 100px);
      gap: 10px;
      background-color: #333;
      padding: 10px;
      border-radius: 8px;
    }

    .tile {
      width: 100px;
      height: 100px;
      display: flex;
      justify-content: center;
      align-items: center;
      font-size: 2rem;
      font-weight: bold;
      border-radius: 6px;
    }

    .tile-0 { background-color: #333; color: transparent; visibility: hidden; }
    .tile-2 { background-color: #eee4da; color: #776e65; }
    .tile-4 { background-color: #ede0c8; color: #776e65; }
    .tile-8  { background-color: #f2b179; color: #f9f6f2; }
    .tile-16 { background-color: #f59563; color: #f9f6f2; }
    .tile-32 { background-color: #f67c5f; color: #f9f6f2; }
    .tile-64 { background-color: #f65e3b; color: #f9f6f2; }
    .tile-128{ background-color: #edcf72; color: #f9f6f2; font-size: 1.5rem; }
    .tile-256{ background-color: #edcc61; color: #f9f6f2; font-size: 1.5rem; }
    .tile-512{ background-color: #edc850; color: #f9f6f2; font-size: 1.5rem; }
    .tile-1024{ background-color: #3c3a32; color: #f9f6f2; font-size: 1.2rem; }
    .tile-2048{ background-color: #3c3a32; color: #f9f6f2; font-size: 1.2rem; }

    #reset {
      margin-top: 20px;
      padding: 10px 20px;
      font-size: 1rem;
      border: none;
