</head>
<body>
  <div class="game-container">
    <div id="score">Score: 0</div>
    <div id="board"></div>
    <button id="reset" onclick="window.game.reset()">New Game</button>
  </div>

  <script>
    window.game = {
      size: 4,
      board: [],
      score: 0,

      reset() {
        this.board = Array(this.size * this.size).fill(0);
        // Add two starting tiles
        const emptyCells = [];
        for (let i = 0; i < this.size * this.size; i++) {
          if (this.board[i] === 0) emptyCells.push(i);
        }
        if (emptyCells.length > 0) {
          this.addRandomTile(emptyCells[0]);
          const remainingEmpty = [];
          for (let i = 0; i < this.size * this.size; i++) {
            if (this.board[i] === 0) remainingEmpty.push(i);
          }
          if (remainingEmpty.length > 0 && Math.random() < 0.9) {
            this.addRandomTile(remainingEmpty[0]);
          }
        }
      },

      addRandomTile(index) {
        const value = Math.random() < 0.9 ? 2 : 4;
        this.board[index] = value;
      },

      move(direction) {
        let moved = false;
        // Transpose if vertical direction
        let boardCopy = [...this.board];
        if (direction === 'up' || direction === 'down') {
          boardCopy = this.transpose(boardCopy);
        }

        // Process each row
        for (let i = 0; i < this.size; i++) {
          const row = [boardCopy[i * this.size], 
                      boardCopy[i * this.size + 1], 
                      boardCopy[i * this.size + 2], 
                      boardCopy[i * this.size + 3]];

          let newRow = slideRow(row);

          // Check if moved in any column of this row
          for (let j = 0; j < this.size; j++) {
            const oldVal = boardCopy[(i * this.size) + j];
            const newVal = newRow[j];
            if (oldVal !== newVal) {
              moved = true;
              break;
            }
          }

          // Update board copy
          for (let j = 0; j < this.size; j++) {
            boardCopy[(i * this.size) + j] = newRow[j];
          }
        }

        // Transpose back if needed
        if (direction === 'up' || direction === 'down') {
          boardCopy = this.transpose(boardCopy);
        }

        // Update actual board
        for (let i = 0; i < this.size * this.size; i++) {
          this.board[i] = boardCopy[i];
        }

        return moved;
      },

      transpose(arr) {
        const size = Math.sqrt(arr.length);
        const result = Array(size * size).fill(0);
        for (let i = 0; i < size; i++) {
          for (let j = 0; j < size; j++) {
            result[j * size + i] = arr[i * size + j];
          }
        }
        return result;
      },

      slideRow(row) {
        // Remove zeros
        let tiles = row.filter(val => val !== 0);

        // Merge adjacent equal values (left to right, no double merge per move)
        for (let i = 0; i < tiles.length - 1; i++) {
          if (tiles[i] === tiles[i + 1]) {
            const mergedValue = tiles[i] * 2;
            tiles[i] = mergedValue;
            this.score += mergedValue; // Add to score on merge
            tiles.splice(i + 1, 1); // Remove merged tile to prevent double merge in same move
          }
        }

        // Pad with zeros
        while (tiles.length < this.size) {
          tiles.push(0);
        }

        return tiles;
      },

      board() {
        return [...this.board];
      },

      setBoard(arr) {
        this.board = arr.slice();
      },

      score() {
        return this.score;
      },

      addRandomTile() {
        const emptyCells = [];
        for (let i = 0; i < this.size * this.size; i++) {
          if (this.board[i] === 0) emptyCells.push(i);
        }
        if (emptyCells.length > 0) {
          const index = Math.floor(Math.random() * emptyCells.length);
          this.addRandomTile(emptyCells[index]);
        }
      }
    };

    // Render the board to DOM
    function renderBoard() {
      const boardEl = document.getElementById('board');
      boardEl.innerHTML = '';

      for (let i = 0; i < window.game.size * window.game.size; i++) {
        const tile = document.createElement('div');
        tile.className = 'tile';

        if (window.game.board[i] !== 0) {
          const value = window.game.board[i];
          let cls = '';
          switch(value) {
            case 2: cls = 'tile-2'; break;
            case 4: cls = 'tile-4'; break;
            case 8: cls = 'tile-8'; break;
            case 16: cls = 'tile-16'; break;
            case 32: cls = 'tile-32'; break;
            case 64: cls = 'tile-64'; break;
            case 128: cls = 'tile-128'; break;
            case 256: cls = 'tile-256'; break;
            case 512: cls = 'tile-512'; break;
            default: cls = value >= 1024 ? 'tile-2048' : 'tile-' + value;
          }
          tile.className += ' ' + cls;
          tile.textContent = value;
        } else {
          tile.className = 'tile-0';
        }

        boardEl.appendChild(tile);
      }
    }

    // Render score to DOM
    function renderScore() {
      document.getElementById('score').textContent = `Score: ${window.game.score}`;
    }

    // Keydown handler for arrow keys
    document.addEventListener('keydown', (e) => {
      const moved = window.game.move(e.key);

      if (moved) {
        renderBoard();
        renderScore();
      }

      // Prevent default scrolling for arrow keys
      if (['ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight'].includes(e.key)) {
        e.preventDefault();
      }
    });

    // Initialize game on load
    window.game.reset();
    renderBoard();
  </script>
</body>
</html>
